import "server-only";
import type { Prisma } from "@/generated/prisma/client";
import { db } from "@/lib/db";
import { BillingError, billingConfig } from "@/lib/billing/config";
import { dodoClient } from "@/lib/billing/dodo";
import { ensureBillingBinding, openCheckoutStates } from "@/lib/billing/store";
import { providerSubscriptions } from "@/lib/billing/checkout";
import { providerSubscriptionSchema } from "@/lib/billing/events";
import { deletionCheckoutSchema, runDeletionJob } from "@/lib/deletion-jobs";

function terminal(provider: {
  status: string;
  cancel_at_next_billing_date: boolean;
}) {
  return (
    ["expired", "failed"].includes(provider.status) ||
    (provider.status === "cancelled" && !provider.cancel_at_next_billing_date)
  );
}

/** Independent of User. Read before every uncertain write; confirm terminal
 * state afterwards. The SDK has bounded requests, retries disabled, test only. */
export async function cancelDeletionBilling(userId: string): Promise<boolean> {
  billingConfig();
  await db.$transaction((tx) => ensureBillingBinding(tx));
  const job = await db.accountDeletionJob.findUniqueOrThrow({
    where: { userId },
  });
  const attempts = deletionCheckoutSchema.parse(job.checkoutRecovery);
  const signal = AbortSignal.timeout(60_000);
  const matchedAttempts = new Set<string>();
  const customers = new Set(job.customerIds);
  // Lost customer-create responses are recovered through server metadata. Email
  // is deliberately unavailable after purge. Include duplicate matching customers.
  if (attempts.length) {
    const earliest = Math.min(...attempts.map((a) => Date.parse(a.createdAt)));
    for await (const customer of dodoClient().customers.list(
      {
        created_at_gte: new Date(earliest - 5 * 60000).toISOString(),
        created_at_lte: new Date(+job.requestedAt + 5 * 60000).toISOString(),
      },
      { signal },
    )) {
      if (
        customer.metadata?.mailloopUserId === userId &&
        attempts.some((a) => a.id === customer.metadata?.checkoutAttemptId)
      )
        customers.add(customer.customer_id);
    }
  }
  await db.accountDeletionJob.updateMany({
    where: { userId },
    data: {
      customerIds: {
        push: [...customers].filter((id) => !job.customerIds.includes(id)),
      },
    },
  });
  const ids = new Set(job.subscriptionIds);
  for (const customerId of customers)
    for (const sub of await providerSubscriptions(customerId, signal))
      ids.add(sub.subscription_id);
  await db.accountDeletionJob.updateMany({
    where: { userId },
    data: {
      subscriptionIds: {
        push: [...ids].filter((id) => !job.subscriptionIds.includes(id)),
      },
    },
  });
  for (const id of ids) {
    let provider = providerSubscriptionSchema.parse(
      await dodoClient().subscriptions.retrieve(id, { signal }),
    );
    if (
      provider.subscription_id !== id ||
      !customers.has(provider.customer.customer_id) ||
      (provider.metadata.mailloopUserId &&
        provider.metadata.mailloopUserId !== userId)
    )
      throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
    if (!terminal(provider)) {
      await dodoClient()
        .subscriptions.update(
          id,
          {
            status: "cancelled",
            cancel_at_next_billing_date: false,
          },
          { signal },
        )
        .catch(() => {});
      provider = providerSubscriptionSchema.parse(
        await dodoClient().subscriptions.retrieve(id, { signal }),
      );
    }
    if (
      provider.subscription_id !== id ||
      !customers.has(provider.customer.customer_id) ||
      (provider.metadata.mailloopUserId &&
        provider.metadata.mailloopUserId !== userId)
    )
      throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
    if (!terminal(provider)) return false;
    if (provider.metadata.checkoutAttemptId)
      matchedAttempts.add(provider.metadata.checkoutAttemptId);
    await db.billingSubscription.updateMany({
      where: { userId, dodoSubscriptionId: id },
      data: {
        status: provider.status.toUpperCase() as
          "CANCELLED" | "EXPIRED" | "FAILED",
        cancelAtPeriodEnd: false,
        gracePeriodEnd: null,
        cancelRequestedAt: null,
      },
    });
  }
  // Still-open hosted checkout can create a subscription after cancellation.
  for (const attempt of attempts) {
    if (["COMPLETED", "FAILED", "EXPIRED"].includes(attempt.status)) continue;
    if (attempt.sessionId) {
      const session = await dodoClient().checkoutSessions.retrieve(
        attempt.sessionId,
        { signal },
      );
      if (
        session.payment_status &&
        !["failed", "cancelled"].includes(session.payment_status) &&
        !matchedAttempts.has(attempt.id)
      )
        return false;
    }
    if (new Date() < new Date(attempt.expiresAt)) return false;
  }
  for (const customerId of customers)
    if (
      (await providerSubscriptions(customerId, signal)).some(
        (s) => !terminal(s),
      )
    )
      return false;
  return true;
}

export async function stopBillingForDeletion(userId: string): Promise<boolean> {
  await runDeletionJob(userId, new Date(), { billingOnly: true });
  return Boolean(
    (
      await db.accountDeletionJob.findUnique({
        where: { userId },
        select: { billingCancelledAt: true },
      })
    )?.billingCancelledAt,
  );
}

export async function assertBillingDeletionSafe(
  tx: Prisma.TransactionClient,
  userId: string,
) {
  if (
    (await tx.checkoutAttempt.count({
      where: { userId, status: { in: openCheckoutStates } },
    })) ||
    (await tx.billingSubscription.count({
      where: { userId, status: { notIn: ["CANCELLED", "EXPIRED", "FAILED"] } },
    }))
  )
    throw new BillingError("BILLING_DELETION_PENDING");
}
